do $migra$
declare
  v_org bigint; v_gtq bigint; r record; v_loc bigint; v_cat bigint; v_id bigint; v_tp bigint; v_tr bigint; v_ex record; v_cta bigint; v_nuevo boolean;
  v_faltan text[] := '{}'; v_choques text[] := '{}'; v_ids bigint[] := '{}';
  p_n int := 0; p_a int := 0; p_s int := 0; l_n int := 0; l_a int := 0; l_s int := 0; l_c int := 0;
begin
  select id into v_org from public.organizaciones where codigo = '3';
  if v_org is null then raise notice 'No existe la organización 3.'; return; end if;
  select id into v_gtq from public.monedas where iso = 'GTQ';
